public class RetryManager {
    private static final Map<Class<? extends Exception>, RetryPolicy> POLICY_MAP = new HashMap<>();

    public void registerRetryPolicy(RetryPolicy policy) {
        POLICY_MAP.put(policy.getClass(), policy);
    }

    public boolean shouldRetry(Exception e) {
        for (RetryPolicy policy : POLICY_MAP.values()) {
            if (policy.shouldRetry(e)) {
                return true;
            }
        }
        return false;
    }

    public void executeRetry(RetryableTask task) throws Exception {
        int retries = 0;
        while (retries < RetryConfig.getMaxRetries()) {
            try {
                task.execute();
            } catch (Exception e) {
                if (shouldRetry(e)) {
                    Thread.sleep(RetryConfig.getRetryDelayMillis()); // wait for retry delay before retrying
                }
                retries++;
            }
        }
        throw new Exception("Failed to execute after " + RetryConfig.getMaxRetries() + " retries");
    }
}
```
