public class RestTemplate {
    private int failureCount = 0;

    public boolean isCircuitBroken() {
        if (failureCount >= 3) {
            return true;
        }
        failureCount++;
        // reset failure count after a certain time period
        try {
            Thread.sleep(1000);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        failureCount = 0;
